package com.bunnidogs.mod.entity;

import com.bunnidogs.mod.genetics.*;
import com.bunnidogs.mod.registry.*;
import com.bunnidogs.mod.society.*;
import java.util.function.Consumer;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.util.ProblemReporter;
import net.minecraft.world.item.*;
import net.minecraft.world.level.storage.TagValueInput;
import net.neoforged.neoforge.common.NeoForge;
import net.neoforged.neoforge.event.entity.EntityMobGriefingEvent;

/** Ordinary helper-profile craftspeople furnish original primitive plots without acquiring architecture. */
final class PrimitiveFurnitureGameTest {
    private static WildFamilyGameTest.Site setup(GameTestHelper h) {
        var initial=WildFamilyGameTest.setup(h,false,false);var home=initial.home();var saved=home.saveWithFullMetadata(h.getLevel().registryAccess());var founders=new net.minecraft.nbt.ListTag();for(int i=0;i<3;i++)founders.add(net.minecraft.nbt.StringTag.valueOf(Genome.DEFAULT.toString()));saved.put("WildFounders",founders);home.loadWithComponents(TagValueInput.create(ProblemReporter.DISCARDING,h.getLevel().registryAccess(),saved));
        for(int i=0;i<3;i++)home.wild().tick();var dogs=home.residents();h.assertTrue(dogs.size()==3 && home.wild().founders().stream().allMatch(Genome.DEFAULT::equals),"The actual frozen ordinary helper-profile founders spawn once, rather than receiving an elite mind or a reroll");
        dogs.forEach(d->{d.setNoAi(true);d.setOnGround(true);h.assertTrue(d.stats().equals(Stats.ZERO) && d.learning().knowledge().equals(Learning.EMPTY) && CapabilityRules.potential(d.mind(),CapabilityRules.Task.BUILDING)==CapabilityRules.Potential.LIMITED && CapabilityRules.potential(d.mind(),CapabilityRules.Task.CRAFTING)==CapabilityRules.Potential.INDEPENDENT,"The untrained ordinary profile can learn crafting but remains genetically limited at architecture");});return new WildFamilyGameTest.Site(h,home,dogs);
    }
    private static boolean craft(WildFamilyGameTest.Site c,Bunnidog dog,CivicRecipes.RecipeId recipe) {return WildFamilyGameTest.act(c,dog,SocietyWork.Kind.CRAFT,c.home().getBlockPos(),recipe.ordinal());}
    static void furniture(GameTestHelper h) {
        var c=setup(h);var home=c.home();var dog=c.dogs().getFirst();for(var log:home.wild().timber())h.assertTrue(WildFamilyGameTest.act(c,dog,SocietyWork.Kind.CLIP_WOOD,log),"The ordinary founder harvests actual original fallen logs");WildFamilyGameTest.collectAll(c,dog);
        for(var recipe:new CivicRecipes.RecipeId[]{CivicRecipes.RecipeId.PLANKS,CivicRecipes.RecipeId.PLANKS,CivicRecipes.RecipeId.PLANKS,CivicRecipes.RecipeId.STICKS,CivicRecipes.RecipeId.WORKBENCH})h.assertTrue(craft(c,dog,recipe),"Personal craft experience comes from the actual paid primitive recipe: "+recipe);
        h.assertTrue(WildFamilyGameTest.build(c,dog,home.construction().cell(home.wild().works().workbench())) && craft(c,dog,CivicRecipes.RecipeId.AXE),"A trained ordinary craftsperson carries and places its paid primitive table before making the native axe");
        for(var field:home.wild().fields())h.assertTrue(WildFamilyGameTest.act(c,dog,SocietyWork.Kind.HARVEST_FIELD,field),"Actual native grain and returned planting seeds supply bedding");WildFamilyGameTest.collectAll(c,dog);var bed=home.wild().beds().getFirst();
        h.assertTrue(craft(c,dog,CivicRecipes.RecipeId.NEST) && WildFamilyGameTest.build(c,dog,home.construction().cell(bed)) && home.construction().owned(bed) && home.count(ModItems.NEST.get())==0,"The original three logs and actual wheat pay for a real carried-and-placed first Nest, without an architect or stocked inputs");
        h.assertTrue(dog.learning().knowledge().knows(Learning.Routine.CRAFT) && dog.learning().knowledge().progress(Learning.Routine.BUILD)==0 && dog.stats().equals(Stats.ZERO),"Primitive furniture does not upload building experience or bred points");
        var wall=home.shelter().stream().filter(cell->cell.item()==ModItems.GUAVA_PLANKS.get()).findFirst().orElseThrow();home.put(new ItemStack(ModItems.GUAVA_PLANKS.get()));WildFamilyGameTest.at(dog,home.getBlockPos());
        h.assertTrue(!dog.society().perform(new SocietyWork.Job(SocietyWork.Kind.FETCH_BUILD,home.getBlockPos(),-1,home.getBlockState(),null,wall.pos())) && home.count(ModItems.GUAVA_PLANKS.get())==1 && dog.society().cargoEmpty(),"The same craftsperson cannot expand this exception into rooms, walls or general architecture");WildFamilyGameTest.clean(c);h.succeed();
    }
    static void limits(GameTestHelper h) {
        var c=setup(h);var home=c.home();var dog=c.dogs().getFirst();var at=home.wild().works().workbench();home.put(new ItemStack(Items.CRAFTING_TABLE));WildFamilyGameTest.at(dog,home.getBlockPos());
        h.assertTrue(!dog.society().perform(new SocietyWork.Job(SocietyWork.Kind.FETCH_BUILD,home.getBlockPos(),-1,home.getBlockState(),null,at)),"Independent potential and a donated table alone do not supply actual craft experience");home.put(new ItemStack(ModItems.GUAVA_LOG.get(),2));h.assertTrue(craft(c,dog,CivicRecipes.RecipeId.PLANKS) && craft(c,dog,CivicRecipes.RecipeId.PLANKS),"Two real hand-sized recipes teach the ordinary craftsperson");
        dog.setGenome(Genome.DEFAULT.with(CognitiveGene.HANDLING,0,2));var foreman=c.dogs().get(2);foreman.setGenome(SocietyGameTest.bright());var known=net.minecraft.world.level.storage.TagValueOutput.createWithContext(ProblemReporter.DISCARDING,h.getLevel().registryAccess());foreman.saveWithoutId(known);var record=known.buildResult();record.putString("Learning",Learning.LEGACY_FAMILIAR.toString());foreman.load(TagValueInput.create(ProblemReporter.DISCARDING,h.getLevel().registryAccess(),record));var bed=home.wild().beds().getFirst();foreman.snapTo(net.minecraft.world.phys.Vec3.atBottomCenterOf(bed.east(2)));home.put(new ItemStack(ModItems.NEST.get()));
        h.assertTrue(CapabilityRules.potential(dog.mind(),CapabilityRules.Task.BUILDING)==CapabilityRules.Potential.SUPPORTED && WildFamilyGameTest.build(c,dog,home.construction().cell(bed)) && dog.society().guided(Learning.Routine.BUILD) && dog.learning().knowledge().progress(Learning.Routine.BUILD)==0,"A nearby real foreman cannot turn zero-Bloom furniture assembly into architecture experience below its physical readiness gate");WildFamilyGameTest.at(dog,home.getBlockPos());
        h.assertTrue(dog.society().perform(new SocietyWork.Job(SocietyWork.Kind.FETCH_BUILD,home.getBlockPos(),-1,home.getBlockState(),null,at)),"The genuinely learned craftsperson fetches the actual original primitive material");var exact=dog.society().workSupplies();
        Consumer<EntityMobGriefingEvent> splice=e->{if(e.getEntity()==dog)dog.setGenome(new Genome(dog.genome().packed(),0));};NeoForge.EVENT_BUS.addListener(splice);
        try {h.assertTrue(!WildFamilyGameTest.act(c,dog,SocietyWork.Kind.BUILD,at) && ItemStack.matches(exact,dog.society().workSupplies()) && !home.construction().owned(at),"A callback limiting craft capacity invalidates primitive placement before payment while retaining the original parcel");}finally {NeoForge.EVENT_BUS.unregister(splice);}
        h.assertTrue(WildFamilyGameTest.act(c,dog,SocietyWork.Kind.DELIVER,home.getBlockPos()) && home.count(Items.CRAFTING_TABLE)==1 && dog.learning().knowledge().progress(Learning.Routine.BUILD)==0,"Safety recovery returns the exact table even after capacity loss, without fictitious architecture");WildFamilyGameTest.clean(c);h.succeed();
    }
    static void ai(GameTestHelper h) {
        var c=setup(h);c.dogs().forEach(d->d.setNoAi(false));long started=h.getLevel().getGameTime();
        h.succeedWhen(()->{var home=c.home();h.assertTrue(home.construction().owned(home.wild().works().workbench()) && home.count(Items.WOODEN_AXE)==1 && home.wild().beds().stream().anyMatch(home.construction()::owned) && c.dogs().stream().anyMatch(d->d.homeNest()!=null && home.wild().beds().contains(d.homeNest()) && home.construction().owned(d.homeNest())),"Ordinary native founders must walk, learn real crafting, make tools and build/claim their first paid Nest without an architect; logs="+home.count(ModItems.GUAVA_LOG.get())+", planks="+home.count(ModItems.GUAVA_PLANKS.get())+", wheat="+home.count(Items.WHEAT)+", jobs="+c.dogs().stream().map(d->String.valueOf(d.society().active())).toList());h.assertTrue(c.dogs().stream().allMatch(d->d.learning().knowledge().progress(Learning.Routine.BUILD)==0 && d.stats().equals(Stats.ZERO)),"The autonomous ordinary family retains its real architectural and physical limits");com.bunnidogs.mod.BunnidogsMod.LOGGER.info("PRIMITIVE_FURNITURE_COMPLETE loaded_ticks={} helper_mind={} guavas_left={}",h.getLevel().getGameTime()-started,c.dogs().getFirst().mind(),home.count(ModItems.GUAVA.get()));WildFamilyGameTest.clean(c);});
    }
    static void family(GameTestHelper h) {
        var c=setup(h);c.dogs().forEach(d->d.setNoAi(false));long started=h.getLevel().getGameTime();
        var maximum=new int[1];var milestones=new long[]{-1,-1,-1};
        h.succeedWhen(()->{
            var home=c.home();maximum[0]=Math.max(maximum[0],home.count(ModItems.GUAVA.get()));var pups=home.residents().stream().filter(d->d.isBaby() && d.society().child()).toList();
            long elapsed=h.getLevel().getGameTime()-started;
            if(milestones[0]<0 && c.dogs().stream().filter(d->d.homeNest()!=null).count()>=2) {milestones[0]=elapsed;com.bunnidogs.mod.BunnidogsMod.LOGGER.info("PRIMITIVE_FAMILY_TWO_HOMES loaded_ticks={}",elapsed);}
            if(milestones[1]<0 && maximum[0]>=20) {milestones[1]=elapsed;com.bunnidogs.mod.BunnidogsMod.LOGGER.info("PRIMITIVE_FAMILY_RESERVE loaded_ticks={}",elapsed);}
            if(milestones[2]<0 && h.getLevel().getBlockEntity(home.wild().nursery()) instanceof com.bunnidogs.mod.block.SeedCropBlockEntity) {milestones[2]=elapsed;com.bunnidogs.mod.BunnidogsMod.LOGGER.info("PRIMITIVE_FAMILY_PLANTED loaded_ticks={}",elapsed);}
            h.assertTrue(!pups.isEmpty(),"The ordinary family must pay for actual courtship/seed/soil growth and a real native litter without player provisioning; guavas="+home.count(ModItems.GUAVA.get())+", max_guavas="+maximum[0]+", wheat="+home.count(Items.WHEAT)+", grain_seeds="+home.count(Items.WHEAT_SEEDS)+", planks="+home.count(ModItems.GUAVA_PLANKS.get())+", residents="+home.residents().size()+", soil="+h.getLevel().getBlockState(home.wild().nursery())+", below="+h.getLevel().getBlockState(home.wild().nursery().below())+", nursery="+home.wild().emptyNursery()+", wheat_meal="+c.dogs().getFirst().canEat(new ItemStack(Items.WHEAT))+", seed_stock="+java.util.stream.IntStream.range(0,home.getContainerSize()).filter(i->SocietyWork.communitySeed(home.getItem(i),home)).count()+", parents="+c.dogs().stream().map(d->"age="+d.getAge()+" home="+d.homeNest()+" pen="+d.readyForPen()+" health="+d.getHealth()+"/"+d.getMaxHealth()+" active="+d.society().active()+" cargo="+d.society().workSupplies()).toList());
            h.assertTrue(pups.stream().allMatch(d->d.learning().knowledge().equals(Learning.EMPTY) && d.society().belongs(home)) && c.dogs().stream().allMatch(d->d.genome().equals(Genome.DEFAULT) && d.stats().equals(Stats.ZERO) && d.learning().knowledge().progress(Learning.Routine.BUILD)==0),"Native children keep actual parented membership and empty learning; their parents acquire neither elite genes nor architecture/bred points");
            com.bunnidogs.mod.BunnidogsMod.LOGGER.info("PRIMITIVE_FAMILY_COMPLETE loaded_ticks={} pups={} guavas_left={}",h.getLevel().getGameTime()-started,pups.size(),home.count(ModItems.GUAVA.get()));WildFamilyGameTest.clean(c);
        });
    }
    static void familyReserve(GameTestHelper h) {
        var c=setup(h);var home=c.home();var worker=c.dogs().get(2);var level=h.getLevel();
        // This policy fixture supplies stock and two beds; family() proves their autonomous paid origin.
        home.put(new ItemStack(ModItems.GUAVA_LOG.get(),3));
        h.assertTrue(craft(c,worker,CivicRecipes.RecipeId.PLANKS) && craft(c,worker,CivicRecipes.RecipeId.PLANKS),"The worker learns crafting from two real recipes before choosing optional chores");
        level.setBlock(home.wild().works().workbench(),net.minecraft.world.level.block.Blocks.CRAFTING_TABLE.defaultBlockState(),3);
        home.put(new ItemStack(Items.WOODEN_AXE));home.put(new ItemStack(ModItems.NEST.get()));home.put(new ItemStack(ModItems.GUAVA.get(),19));
        for(int i=0;i<2;i++) {var parent=c.dogs().get(i);var bed=home.wild().beds().get(i);level.setBlock(bed,ModBlocks.NEST.get().defaultBlockState(),3);level.getPoiManager().add(bed,ModPoi.NEST);WildFamilyGameTest.at(parent,bed);if(i==0)h.assertTrue(parent.moveHomeTo(level,bed)==NestHome.MoveResult.MOVED,"The first real parent claims its Nest");}
        WildFamilyGameTest.at(worker,home.getBlockPos());var optional=worker.society().offers();
        h.assertTrue(optional.stream().anyMatch(j->j.kind()==SocietyWork.Kind.CRAFT && j.index()==CivicRecipes.RecipeId.PLANKS.ordinal()),"One housed parent cannot stop ordinary affordable work for an impossible litter");
        var bed=home.wild().beds().get(2);h.assertTrue(worker.society().perform(new SocietyWork.Job(SocietyWork.Kind.FETCH_BUILD,home.getBlockPos(),-1,home.getBlockState(),null,bed)),"An actual original paid Nest leaves stock before family preparation begins");var exact=worker.society().workSupplies();
        var second=c.dogs().get(1);WildFamilyGameTest.at(second,home.wild().beds().get(1));h.assertTrue(second.moveHomeTo(level,home.wild().beds().get(1))==NestHome.MoveResult.MOVED,"The second real parent creates the actual family opportunity");WildFamilyGameTest.at(worker,home.getBlockPos());
        h.assertTrue(worker.society().offers().stream().anyMatch(j->j.kind()==SocietyWork.Kind.BUILD && j.target().equals(bed)) && ItemStack.matches(exact,worker.society().workSupplies()),"Family preparation never strands an already-paid walking construction parcel");
        h.assertTrue(WildFamilyGameTest.act(c,worker,SocietyWork.Kind.DELIVER,home.getBlockPos()) && home.count(ModItems.NEST.get())==1,"The actual Nest can still return safely to its original stock");WildFamilyGameTest.at(worker,home.getBlockPos());
        CivicFields.scatter(home,home.orchard().getFirst(),java.util.List.of(new ItemStack(ModItems.GUAVA.get()),new ItemStack(ModItems.GUAVA_LOG.get())));level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(home.getBlockPos()).inflate(24)).forEach(item->item.setNoPickUpDelay());
        var gathering=worker.society().offers();
        h.assertTrue(gathering.stream().anyMatch(j->j.kind()==SocietyWork.Kind.PRUNE) && gathering.stream().anyMatch(j->j.kind()==SocietyWork.Kind.GATHER_FIELD && level.getEntity(j.index()) instanceof net.minecraft.world.entity.item.ItemEntity item && item.getItem().is(ModItems.GUAVA.get())) && gathering.stream().noneMatch(j->j.kind()==SocietyWork.Kind.CRAFT || j.kind()==SocietyWork.Kind.FETCH_BUILD || j.kind()==SocietyWork.Kind.HARVEST_FIELD || j.kind()==SocietyWork.Kind.GATHER_FIELD && level.getEntity(j.index()) instanceof net.minecraft.world.entity.item.ItemEntity item && item.getItem().is(ModItems.GUAVA_LOG.get())),"Ready housed parents preserve their reserve through useful food gathering, without optional wood, bedding, or inedible wheat bills");
        var patient=ModEntities.BUNNIDOG.get().create(level,net.minecraft.world.entity.EntitySpawnReason.COMMAND);patient.setGenome(Genome.DEFAULT);patient.setStats(Stats.ZERO);patient.setAge(0);patient.setHealth(patient.getMaxHealth());patient.setNoAi(true);patient.society().settle(home);var recovery=home.getBlockPos().west(8);level.setBlock(recovery,ModBlocks.NEST.get().defaultBlockState(),3);level.getPoiManager().add(recovery,ModPoi.NEST);WildFamilyGameTest.at(patient,recovery);level.addFreshEntity(patient);
        h.assertTrue(patient.moveHomeTo(level,recovery)==NestHome.MoveResult.MOVED,"An actual fourth citizen claims its recovery bed");patient.snapTo(net.minecraft.world.phys.Vec3.atBottomCenterOf(recovery.north(5)));var enemy=h.spawnWithNoFreeWill(net.minecraft.world.entity.EntityTypes.HUSK,34,180,25);h.assertTrue(patient.hurtServer(level,level.damageSources().mobAttack(enemy),100) && patient.combat().downed(),"A real lethal mob hit creates an urgent civic rescue need");enemy.discard();var saved=net.minecraft.world.level.storage.TagValueOutput.createWithContext(ProblemReporter.DISCARDING,level.registryAccess());patient.saveWithoutId(saved);var quiet=saved.buildResult();quiet.putInt("CombatDanger",0);patient.load(TagValueInput.create(ProblemReporter.DISCARDING,level.registryAccess(),quiet));
        worker.setStats(Stats.ZERO.with(Stat.BLOOM,10));home.put(new ItemStack(Items.LEATHER));home.put(new ItemStack(Items.LEAD));
        h.assertTrue(CivicRescue.needsBasket(home) && worker.society().offers().stream().anyMatch(j->j.kind()==SocietyWork.Kind.CRAFT && j.index()==CivicRecipes.RecipeId.BASKET.ordinal()),"An affordable native basket for an actual downed citizen remains available during family preparation to a physically ready craftsperson");patient.discard();worker.setStats(Stats.ZERO);
        home.put(new ItemStack(ModItems.GUAVA.get()));var court=worker.society().plan();
        h.assertTrue(court!=null && court.kind()==SocietyWork.Kind.COURT && WildFamilyGameTest.act(c,worker,SocietyWork.Kind.COURT,home.getBlockPos()) && home.count(ModItems.GUAVA.get())==18 && c.dogs().get(0).isInLove() && second.isInLove(),"At the existing twenty-guava threshold a real carer selects courtship and pays exactly two, before optional chores");WildFamilyGameTest.at(worker,home.getBlockPos());
        h.assertTrue(worker.society().offers().stream().anyMatch(j->j.kind()==SocietyWork.Kind.CRAFT && j.index()==CivicRecipes.RecipeId.PLANKS.ordinal()),"Once the real parents court, the remaining helper resumes ordinary work instead of holding a stale family lock");WildFamilyGameTest.clean(c);h.succeed();
    }
    static void foodTool(GameTestHelper h) {
        var c=setup(h);var home=c.home();var worker=c.dogs().getFirst();var level=h.getLevel();
        for(var log:home.wild().timber().subList(1,3))h.assertTrue(WildFamilyGameTest.act(c,worker,SocietyWork.Kind.CLIP_WOOD,log),"Actual finite wood starts the hungry worker's food-tool chain");WildFamilyGameTest.collectAll(c,worker);
        for(var recipe:new CivicRecipes.RecipeId[]{CivicRecipes.RecipeId.PLANKS,CivicRecipes.RecipeId.PLANKS,CivicRecipes.RecipeId.STICKS,CivicRecipes.RecipeId.WORKBENCH})h.assertTrue(craft(c,worker,recipe),"Real paid primitive work exhausts the ration budget: "+recipe);WildFamilyGameTest.at(worker,home.getBlockPos());
        h.assertTrue(home.count(ModItems.GUAVA.get())==0 && home.count(ModItems.GUAVA_PLANKS.get())==2 && worker.society().offers().stream().anyMatch(j->j.kind()==SocietyWork.Kind.FETCH_BUILD && home.wild().works().workbench().equals(j.destination())) && WildFamilyGameTest.build(c,worker,home.construction().cell(home.wild().works().workbench())),"A hungry resident can still carry and place its actual paid table when that station is the missing link to ripe orchard food");WildFamilyGameTest.at(worker,home.getBlockPos());
        var last=home.wild().timber().getFirst();h.assertTrue(worker.society().offers().stream().anyMatch(j->j.kind()==SocietyWork.Kind.CLIP_WOOD && j.target().equals(last)) && WildFamilyGameTest.act(c,worker,SocietyWork.Kind.CLIP_WOOD,last),"Ration exhaustion does not forbid the last original log needed for the food-unlocking axe");level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(home.getBlockPos()).inflate(24)).forEach(item->item.setNoPickUpDelay());WildFamilyGameTest.at(worker,home.getBlockPos());
        h.assertTrue(worker.society().offers().stream().anyMatch(j->j.kind()==SocietyWork.Kind.GATHER_FIELD && level.getEntity(j.index()) instanceof net.minecraft.world.entity.item.ItemEntity item && item.getItem().is(ModItems.GUAVA_LOG.get())),"The hungry worker may walk home that actual marked emergency wood");WildFamilyGameTest.collectAll(c,worker);
        h.assertTrue(craft(c,worker,CivicRecipes.RecipeId.PLANKS) && craft(c,worker,CivicRecipes.RecipeId.AXE) && home.count(Items.WOODEN_AXE)==1 && home.count(ModItems.GUAVA.get())==0,"Original wood and native recipes make the real axe without any supplied meal or material");WildFamilyGameTest.at(worker,home.getBlockPos());
        h.assertTrue(worker.society().offers().stream().anyMatch(j->j.kind()==SocietyWork.Kind.PRUNE) && WildFamilyGameTest.act(c,worker,SocietyWork.Kind.PRUNE,home.orchard().getFirst()),"The actual tool unlocks the original ripe orchard while the ration is still owed");level.getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(home.getBlockPos()).inflate(24)).forEach(item->item.setNoPickUpDelay());WildFamilyGameTest.at(worker,home.getBlockPos());var food=worker.society().offers().stream().filter(j->j.kind()==SocietyWork.Kind.GATHER_FIELD && level.getEntity(j.index()) instanceof net.minecraft.world.entity.item.ItemEntity item && item.getItem().is(ModItems.GUAVA.get())).findFirst().orElseThrow();
        h.assertTrue(WildFamilyGameTest.act(c,worker,SocietyWork.Kind.GATHER_FIELD,food.target(),food.index()) && WildFamilyGameTest.act(c,worker,SocietyWork.Kind.DELIVER,home.getBlockPos()),"A real one-item guava parcel reaches the original common store");WildFamilyGameTest.at(worker,home.getBlockPos());
        h.assertTrue(worker.society().plan().kind()==SocietyWork.Kind.MEAL && WildFamilyGameTest.act(c,worker,SocietyWork.Kind.MEAL,home.getBlockPos()) && home.count(ModItems.GUAVA.get())==0 && worker.stats().equals(Stats.ZERO),"The recovered real guava pays the same existing ration before ordinary work resumes; the emergency exception grants no free food or body points");WildFamilyGameTest.clean(c);h.succeed();
    }
}
